import L from 'leaflet';
import person from './assets/person-half.svg'
import alert from './assets/alert.svg'
import house from './assets/house.svg'
import money from './assets/money-bag.svg'
import farmers from './assets/farmers.svg'
import church from './assets/church.svg'
import merchants from './assets/merchants.svg'
import thieves from './assets/thieves.svg'
import players from './assets/red-marker.svg'

// Construct each icon's SVG file.
export const Icons = Object.freeze({
    PERSON: "person",
    ALERT: "alert",
    HOUSE: "house",
    MONEY: "money",
    FARMERS: "farmers",
    CHURCH: "church",
    MERCHANTS: "merchants",
    THIEVES: "thieves",
    PLAYERS: "players"
});

// Given an icon name, return the corresponding SVG file.
export const getIconSvg = (icon) => {
    return  {
        [Icons.PERSON]: person,
        [Icons.ALERT]: alert,
        [Icons.HOUSE]: house,
        [Icons.MONEY]: money,
        [Icons.FARMERS]: farmers,
        [Icons.CHURCH]: church,
        [Icons.MERCHANTS]: merchants,
        [Icons.THIEVES]: thieves,
        [Icons.PLAYERS]: players
    }[icon]
}

// Create and return a new Icon object.  If no parameter is passed, create a
// blank red icon.  Otherwise, if given an icon name, attempt to find the
// corresoponding SVG file.
export const createIcon = (icon = Icons.RED, zoomLevel = 1) => {
    const iconvg = getIconSvg(icon)
    const dim = 38 * (zoomLevel / 3)

    return new L.Icon({
        iconUrl: iconvg,
        iconRetinaUrl: iconvg,
        popupAnchor:  [0, 0],
        iconAnchor: [19, 17],
        iconSize: [dim,dim],     
    })
}
